-- Clubwerk Demo-Daten (erfunden): Verkauf. Bearbeiten: siehe werkzeuge/demo/aufteilen.js
BEGIN;
CREATE TABLE IF NOT EXISTS "articles" (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  name        TEXT NOT NULL,
  category    TEXT NOT NULL DEFAULT 'Sonstiges',
  price_cents INTEGER NOT NULL DEFAULT 0 CHECK (price_cents >= 0),
  crate_size  INTEGER NOT NULL DEFAULT 1 CHECK (crate_size >= 1),
  min_stock   INTEGER NOT NULL DEFAULT 0,
  track_stock INTEGER NOT NULL DEFAULT 1,
  active      INTEGER NOT NULL DEFAULT 1,
  sort        INTEGER NOT NULL DEFAULT 100
, target_stock INTEGER NOT NULL DEFAULT 0, custom INTEGER NOT NULL DEFAULT 0, icon TEXT, image TEXT, deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS "bookings" (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  member_id    INTEGER REFERENCES members(id),
  article_id   INTEGER NOT NULL REFERENCES articles(id),
  event_id     INTEGER REFERENCES events(id),
  kind         TEXT NOT NULL CHECK (kind IN ('konto','verein','gast','event')),
  qty          INTEGER NOT NULL CHECK (qty > 0),
  unit_cents   INTEGER NOT NULL,
  total_cents  INTEGER NOT NULL,
  created_at   TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  cancelled_at TEXT,
  cancelled_by TEXT
, paid_cash INTEGER, transferred_at TEXT, transferred_by TEXT, event_guest_id INTEGER REFERENCES event_guests(id), payment_id INTEGER REFERENCES event_payments(id), note TEXT, tab_id INTEGER REFERENCES guest_tabs(id), settled_id INTEGER REFERENCES member_settlements(id), credit_for INTEGER, article_name TEXT, article_category TEXT);
CREATE TABLE IF NOT EXISTS "deliveries" (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  date        TEXT NOT NULL,
  supplier    TEXT NOT NULL,
  note        TEXT,
  created_at  TEXT NOT NULL DEFAULT (datetime('now','localtime'))
, doc_no TEXT, doc_kind TEXT NOT NULL DEFAULT 'lieferung', file TEXT, total_cents INTEGER);
CREATE TABLE IF NOT EXISTS "delivery_items" (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  delivery_id INTEGER NOT NULL REFERENCES deliveries(id) ON DELETE CASCADE,
  article_id  INTEGER NOT NULL REFERENCES articles(id),
  crates      INTEGER NOT NULL DEFAULT 0,
  bottles     INTEGER NOT NULL DEFAULT 0
, supplier_art_no TEXT, supplier_text TEXT, cost_cents INTEGER);
CREATE TABLE IF NOT EXISTS event_articles (
  event_id    INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  article_id  INTEGER NOT NULL REFERENCES articles(id),
  price_cents INTEGER NOT NULL CHECK (price_cents >= 0),
  PRIMARY KEY (event_id, article_id)
);
CREATE TABLE IF NOT EXISTS "event_guests" (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  event_id    INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  name        TEXT NOT NULL,
  member_id   INTEGER REFERENCES members(id),
  created_at  TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  created_by  TEXT
);
CREATE TABLE IF NOT EXISTS "event_payments" (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  event_id    INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  guest_id    INTEGER NOT NULL REFERENCES event_guests(id) ON DELETE CASCADE,
  method      TEXT NOT NULL CHECK (method IN ('bar','karte')),
  cents       INTEGER NOT NULL,
  at          TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  by_user     TEXT
);
CREATE TABLE IF NOT EXISTS "events" (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  name        TEXT NOT NULL,
  date        TEXT NOT NULL,
  active      INTEGER NOT NULL DEFAULT 0,
  cash_cents  INTEGER,
  note        TEXT,
  created_at  TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  closed_at   TEXT
, deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS "guest_tabs" (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  name        TEXT NOT NULL,
  status      TEXT NOT NULL DEFAULT 'offen' CHECK (status IN ('offen','bezahlt','uebernommen','abgeschrieben')),
  method      TEXT CHECK (method IN ('bar','karte')),
  cents       INTEGER,
  member_id   INTEGER REFERENCES members(id),
  note        TEXT,
  created_at  TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  created_by  TEXT,
  closed_at   TEXT,
  closed_by   TEXT
);
CREATE TABLE IF NOT EXISTS "member_settlements" (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  member_id   INTEGER NOT NULL REFERENCES members(id),
  cents       INTEGER NOT NULL,
  items       INTEGER NOT NULL DEFAULT 0,
  until_at    TEXT NOT NULL,
  batch       TEXT,
  note        TEXT,
  by_user     TEXT,
  created_at  TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE IF NOT EXISTS "settlements" (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  until_date  TEXT NOT NULL,
  note        TEXT,
  created_at  TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE IF NOT EXISTS "stock_moves" (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  article_id  INTEGER NOT NULL REFERENCES articles(id),
  qty         INTEGER NOT NULL,
  reason      TEXT NOT NULL CHECK (reason IN ('bruch','inventur','korrektur')),
  date        TEXT NOT NULL,
  note        TEXT,
  created_at  TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE IF NOT EXISTS supplier_map (
  supplier    TEXT NOT NULL,
  art_no      TEXT NOT NULL,
  article_id  INTEGER REFERENCES articles(id),
  pack_size   INTEGER NOT NULL DEFAULT 1,
  text        TEXT,
  PRIMARY KEY (supplier, art_no)
);
CREATE INDEX IF NOT EXISTS ix_bookings_article ON bookings(article_id) WHERE cancelled_at IS NULL;
CREATE INDEX IF NOT EXISTS ix_bookings_created ON bookings(created_at);
CREATE INDEX IF NOT EXISTS ix_bookings_credit ON bookings(credit_for);
CREATE INDEX IF NOT EXISTS ix_bookings_event ON bookings(event_id);
CREATE INDEX IF NOT EXISTS ix_bookings_guest ON bookings(event_guest_id);
CREATE INDEX IF NOT EXISTS ix_bookings_member  ON bookings(member_id);
CREATE INDEX IF NOT EXISTS ix_bookings_open ON bookings(member_id) WHERE settled_id IS NULL;
CREATE INDEX IF NOT EXISTS ix_bookings_payment ON bookings(payment_id);
CREATE INDEX IF NOT EXISTS ix_bookings_tab ON bookings(tab_id);
CREATE INDEX IF NOT EXISTS ix_delivery_items_article ON delivery_items(article_id);
CREATE INDEX IF NOT EXISTS ix_guests_event ON event_guests(event_id);
CREATE INDEX IF NOT EXISTS ix_guests_member ON event_guests(member_id);
CREATE INDEX IF NOT EXISTS ix_msettle_member ON member_settlements(member_id);
CREATE INDEX IF NOT EXISTS ix_stock_moves_article ON stock_moves(article_id);
CREATE INDEX IF NOT EXISTS ix_tabs_status ON guest_tabs(status);
CREATE UNIQUE INDEX IF NOT EXISTS ux_deliveries_doc ON deliveries(supplier, doc_no) WHERE doc_no IS NOT NULL;
COMMIT;
